# DK HRH.  Hjørring - Hørby
#
let hh = path("d3.dk.hrh");

with detail = 4, railway = :first :pax :removed {
    # point.dk.Hjørring  dk.FFH

    with link = "line.dk.HRH" {
        with layer = -1 track(:station,
            path("d3.dk.hrh.hjv")[:hjv + 230m, :hjo.xh]
        );

        track(:ror:lor,
                hh[:hjo.yh - 0.1dl, :hjo.yh] >> 1mo
            ..  hh[:hjo.xh, :hjo.xh + 0.1dl]
        );
        track(:casing, hh[:hjo.xh, :hjo.xh + 2.41km]);
        line_label(:left:sw, hh[:hjo.xh + 2.4km] << 0.5mt, "HRH");
        track(hh[:hjo.xh + 2.39km, :fug - 0.49sw]);
    }

    with link = "point.dk.Fuglsig", railway = :station {
        track(hh[:fug - 0.5sw, :fug + 0.5sw]);
        marker(:left :de.hp, hh[:fug] << 0.5mt);
        station(:top, hh[:fug] << 0.5mt << 1sh + (1.3dt, -0.8dt),
            "Fuglsig", "HRH: ??"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:fug + 0.49sw, :ilb - 0.49sw]);
    }

    with link = "point.dk.Ilbro", railway = :station {
        track(hh[:ilb - 0.5sw, :ilb + 0.5sw]);
        marker(:right :de.bf, hh[:ilb] >> 0.5mt);
        station(:bottom, hh[:ilb] >> 0.5mt >> 1sh >> 0.8dt,
            "Ilbro", "HRH: 6,7"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:ilb + 0.49sw, :lor - 0.49sw]);
    }

    with link = "point.dk.Lørslev", railway = :station {
        track(hh[:lor - 0.5sw, :lor + 0.5sw]);
        marker(:left :de.bf, hh[:lor] << 0.5mt);
        station(:top, hh[:lor] << 0.5mt << 1sh + (0.5dt, -0.8dt),
            "Lørslev", "HRH: 8,9"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:lor + 0.49sw, :boj - 0.49sw]);
    }

    with link = "point.dk.Bøjholm", railway = :station {
        track(hh[:boj - 0.5sw, :boj + 0.5sw]);
        marker(:left :de.hp, hh[:boj] << 0.5mt);
        station(:right, hh[:boj] << 0.5mt << 1sh + (1.5dt, 1.3dt),
            "Bøjholm", "HRH: 11,6"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:boj + 0.49sw, :tar - 0.49sw]);
    }

    with link = "point.dk.Tårs", railway = :station {
        track(hh[:tar - 0.5sw, :tar + 0.5sw]);
        marker(:left :de.bf, hh[:tar] << 0.5mt);
        station(:right:left_align, hh[:tar] << 0.5mt << 1sh + (2dt, 1.7dt),
            "Tårs", " HRH: 14,0"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:tar + 0.49sw, :bjo - 0.49sw]);
    }

    with link = "point.dk.Bjørnstrup", railway = :station {
        track(hh[:bjo - 0.5sw, :bjo + 0.5sw]);
        marker(:right :de.hp, hh[:bjo] >> 0.5mt);
        station(:left, hh[:bjo] >> 0.5mt >> 1sh + (-1.7dt, 1.8dt),
            "Bjørnstrup", "HRH: ??"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:bjo + 0.49sw, :tra - 0.49sw]);
    }

    with link = "point.dk.Tranget", railway = :station {
        track(hh[:tra - 0.5sw, :tra + 0.5sw]);
        marker(:right :de.bf, hh[:tra] >> 0.5mt);
        station(:bottom, hh[:tra] >> 0.5mt >> 1sh + (-0.3dt, 0.8dt),
            "Tranget", "HRH: 17,8"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:tra + 0.49sw, :sas - 0.49sw]);
    }

    with link = "point.dk.Sæsing", railway = :station {
        track(hh[:sas - 0.5sw, :sas + 0.5sw]);
        marker(:left :de.bf, hh[:sas] << 0.5mt);
        station(:top, hh[:sas] << 0.5mt << 1sh + (1dt, -1dt),
            "Sæsing", "HRH: 20,8"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:sas + 0.49sw, :dal - 0.49sw]);
    }

    with link = "point.dk.Dalvang", railway = :station {
        track(hh[:dal - 0.5sw, :dal + 0.5sw]);
        marker(:right :de.hp, hh[:dal] >> 0.5mt);
        station(:left, hh[:dal] >> 0.5mt >> 1sh + (-1.7dt, 1.8dt),
            "Dalvang", "HRH: 22,5"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:dal + 0.49sw, :dal + 0.81km]);
        line_label(:left:sw, hh[:dal + 0.8km] << 0.5mt, "HRH");
        track(hh[:dal + 0.79km, :ost.yv - 0.49seg]);
    }

    with link = "point.dk.Østervrå", railway = :station {
        track(hh[:ost.yv - 0.5seg, :ost + 380m]);
        track(
                hh[:ost.yv, :ost + 350m - 1dl] >> 1mo
            --  hh[:ost + 350m, :ost + 351m]
        );
        marker(:right :de.bf, hh[:ost] >> 1mo >> 0.5mt);
        station(:bottom, hh[:ost] >> 1mo >> 0.5mt >> 1sh + (1.5dt, 1dt),
            span(:bold, "Østervrå"),
            hbox(:center:top,
                vbox(:right:top, "HRH: ", "VOV: "),
                vbox(:sep:top,
                    hbox(:sep:base, "24,", anchor(), "8"),
                    hbox(:sep:base, "36,", anchor(), "5")
                )
            )
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:ost + 379m, :ost + 1.01km]);
        line_label(:left:s, hh[:ost + 1km] << 0.5mt, (-0.3dt, 0dt), "HRH");
        track(hh[:ost + 0.99km, :lin - 0.49sw]);
    }

    with link = "point.dk.Lindholm-Nordjylland", railway = :station {
        track(hh[:lin - 0.5sw, :lin + 0.5sw]);
        marker(:left :de.hp, hh[:lin] << 0.5mt);
        station(:top, hh[:lin] << 0.5mt << 1sh + (1dt, -0.8dt),
            "Lindholm", "HRH: 26,7"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:lin + 0.49sw, :tho - 0.49sw]);
    }

    with link = "point.dk.Thorshøj", railway = :station {
        track(hh[:tho - 0.5sw, :tho + 0.5sw]);
        marker(:right :de.bf, hh[:tho] >> 0.5mt);
        station(:left, hh[:tho] >> 0.5mt >> 1sh + (-2.0dt, 1.8dt),
            "Thorshøj", "HRH: 29,6"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:tho + 0.49sw, :tam - 0.49sw]);
    }

    with link = "point.dk.Tamstrup", railway = :station {
        track(hh[:tam - 0.5sw, :tam + 0.5sw]);
        marker(:right :de.hp, hh[:tam] >> 0.5mt);
        station(:bottom, hh[:tam] >> 0.5mt >> 1sh + (-1dt, 1dt),
            "Tamstrup", "HRH: 32,1"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:tam + 0.49sw, :tam + 1.41km]);
        line_label(:left:s, hh[:tam + 1.4km] << 0.5mt, (-0.3dt, 0dt), "HRH");
        track(hh[:tam + 1.39km, :hor.xb]);
        track(:lor,
                hh[:hor.xb - 0.1dl, :hor.xb]
            ..  hh[:hor.yb, :hor.yb + 0.1dl] >> 1mo
        );
    }

    # point.dk.Hørby  dk.NFH
}

